fail.message:
@{failuremessage}
SERVER INIT COMMAND (once, if the data directory is not initialized): ${psql.server.init.command}
SERVER COMMAND (if PostgreSQL is stopped): ${psql.server.start.command}
PSQL COMMAND: ${psql.executable} --no-psqlrc --no-password --host=@{host} --port=@{port} --username=@{username} --dbname=@{database} --tuples-only --no-align --quiet --command="@{command}"
PASSWORD: supplied through PGPASSWORD (not printed).

exec.inputstring:
\set target_user :ENV.PSQL_TARGET_USER
\set target_password :ENV.PSQL_TARGET_PASSWORD
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = :'target_user') THEN
    EXECUTE format('CREATE ROLE %I LOGIN', :'target_user');
  END IF;
END
$do$;
ALTER ROLE :"target_user" LOGIN PASSWORD :'target_password' CREATEDB;

\set target_user :ENV.PSQL_TARGET_USER
\set target_password :ENV.PSQL_TARGET_PASSWORD
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = :'target_user') THEN
    EXECUTE format('CREATE ROLE %I LOGIN', :'target_user');
  END IF;
END
$do$;
ALTER ROLE :"target_user" LOGIN PASSWORD :'target_password' CREATEDB;
